import React, { useMemo } from 'react';
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import { DOC_COUNTS, COLORS } from '../../constants';
import CustomTooltip from '../CustomTooltip';
import CustomLegend from '../CustomLegend';
import ExplanationCard from '../ExplanationCard';

const MethodComparisonView = ({ selectedMethodsForComparison, comparisonModel, methodData, selectedLanguages }) => {
  const getMethodStrokePattern = (methodIndex) => {
    const patterns = ['0', '5 5', '10 5', '15 5 5 5', '20 5 5 5 5 5'];
    return patterns[methodIndex % patterns.length];
  };

  const comparisonData = useMemo(() => {
    if (!selectedMethodsForComparison.length || !comparisonModel) return [];
    
    return DOC_COUNTS.map(docCount => {
      const dataPoint = { docCount };
      
      selectedMethodsForComparison.forEach(method => {
        if (methodData[method] && methodData[method][comparisonModel]) {
          selectedLanguages.forEach(lang => {
            const values = methodData[method][comparisonModel][lang] || [];
            const docIndex = DOC_COUNTS.indexOf(docCount);
            dataPoint[`${method}_${lang}`] = values[docIndex] || null;
          });
        }
      });
      
      return dataPoint;
    });
  }, [selectedMethodsForComparison, comparisonModel, methodData, selectedLanguages]);

  const comparisonStats = useMemo(() => {
    if (!selectedMethodsForComparison.length || !comparisonModel) return [];
    
    const stats = [];
    
    selectedMethodsForComparison.forEach(method => {
      if (methodData[method] && methodData[method][comparisonModel]) {
        selectedLanguages.forEach(lang => {
          const values = methodData[method][comparisonModel][lang] || [];
          const validValues = values.filter(val => val !== null && val !== undefined && !isNaN(val));
          
          if (validValues.length > 0) {
            const maxValue = Math.max(...validValues);
            const maxIndex = values.indexOf(maxValue);
            const minValue = Math.min(...validValues);
            const meanValue = validValues.reduce((a, b) => a + b, 0) / validValues.length;
            const improvement = validValues.length > 0 ? maxValue - (values[0] || 0) : 0;
            
            stats.push({
              method,
              language: lang,
              maxScore: maxValue,
              minScore: minValue,
              meanScore: meanValue,
              optimalDocCount: DOC_COUNTS[maxIndex],
              improvement,
              consistency: validValues.length > 1 ? Math.sqrt(validValues.map(v => Math.pow(v - meanValue, 2)).reduce((a, b) => a + b, 0) / (validValues.length - 1)) : 0
            });
          }
        });
      }
    });
    
    return stats;
  }, [selectedMethodsForComparison, comparisonModel, methodData, selectedLanguages]);

  const winnersAnalysis = useMemo(() => {
    if (!comparisonStats.length) return {};
    
    // Best overall performer
    const bestOverall = comparisonStats.reduce((best, current) => 
      current.maxScore > best.maxScore ? current : best
    );
    
    // Best per language
    const bestPerLanguage = {};
    selectedLanguages.forEach(lang => {
      const langStats = comparisonStats.filter(stat => stat.language === lang);
      if (langStats.length > 0) {
        bestPerLanguage[lang] = langStats.reduce((best, current) => 
          current.maxScore > best.maxScore ? current : best
        );
      }
    });
    
    // Most consistent performer
    const mostConsistent = comparisonStats.reduce((best, current) => 
      current.consistency < best.consistency ? current : best
    );
    
    // Best improvement
    const bestImprovement = comparisonStats.reduce((best, current) => 
      current.improvement > best.improvement ? current : best
    );
    
    return {
      bestOverall,
      bestPerLanguage,
      mostConsistent,
      bestImprovement
    };
  }, [comparisonStats, selectedLanguages]);

  if (selectedMethodsForComparison.length < 2 || !comparisonModel) {
    return (
      <div className="mb-8">
        <h3 className="text-3xl font-bold text-gray-800 mb-3 text-center">
          Method Comparison Analysis
        </h3>
        <div className="text-center py-8">
          <p className="text-gray-600 mb-4">Select at least 2 methods and a model to compare performance.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="mb-8">
      <ExplanationCard title="Method Comparison Explanation">
        <p><strong>Line Chart:</strong> Compares performance trajectories of selected methods across document counts. Different line patterns distinguish methods, colors represent languages.</p>
        <p><strong>Interpretation:</strong> Look for which method (line pattern) performs best for each language (color) across different document counts.</p>
        <p><strong>Line Patterns:</strong> Solid lines = first method, dashed lines = other methods with varying patterns.</p>
        <p><strong>Best Practice:</strong> Compare methods at optimal document counts for each language to identify the most effective approach.</p>
      </ExplanationCard>

      <h3 className="text-3xl font-bold text-gray-800 mb-3 text-center">
        Method Comparison Analysis
      </h3>
      <p className="text-lg text-gray-600 text-center mb-8">
        Comparing methods: {selectedMethodsForComparison.join(', ')} for {comparisonModel} model.
      </p>
      
      <div className="bg-gray-50 rounded-xl p-8 shadow-inner border border-gray-200">
        <ResponsiveContainer width="100%" height={500}>
          <LineChart data={comparisonData} margin={{ top: 20, right: 40, left: 20, bottom: 60 }}>
            <CartesianGrid strokeDasharray="4 4" stroke="#e0e7ff" />
            <XAxis 
              dataKey="docCount" 
              label={{ value: 'Number of Documents (Doc Count)', position: 'bottom', offset: 25, fill: '#4a5568', fontSize: '15px', fontWeight: 'bold' }}
              tickLine={false}
              axisLine={{ stroke: '#cbd5e0' }}
              padding={{ left: 15, right: 15 }}
            />
            <YAxis 
              label={{ value: 'Performance Score', angle: -90, position: 'left', offset: 10, fill: '#4a5568', fontSize: '15px', fontWeight: 'bold' }}
              tickLine={false}
              axisLine={{ stroke: '#cbd5e0' }}
              domain={['dataMin - 10', 'dataMax + 10']}
            />
            <Tooltip content={<CustomTooltip />} />
            <Legend content={<CustomLegend />} />
            {selectedMethodsForComparison.map((method, methodIdx) =>
              selectedLanguages.map(lang => (
                <Line
                  key={`${method}_${lang}`}
                  type="monotone"
                  dataKey={`${method}_${lang}`}
                  stroke={COLORS[lang]}
                  strokeWidth={3}
                  strokeDasharray={getMethodStrokePattern(methodIdx)}
                  dot={{ r: 6, fill: COLORS[lang] }}
                  name={`${method} (${lang})`}
                  connectNulls={false}
                />
              ))
            )}
          </LineChart>
        </ResponsiveContainer>
        
        {/* Legend explanation for line patterns */}
        <div className="mt-4 p-4 bg-white rounded-lg border border-gray-200">
          <h5 className="text-sm font-semibold text-gray-700 mb-2">Line Pattern Guide:</h5>
          <div className="flex flex-wrap gap-4 text-xs text-gray-600">
            {selectedMethodsForComparison.map((method, index) => (
              <div key={method} className="flex items-center">
                <div 
                  className="w-8 h-1 mr-2 border-t-2 border-gray-600"
                  style={{ 
                    borderStyle: getMethodStrokePattern(index) === '0' ? 'solid' : 'dashed',
                    borderTopWidth: '2px'
                  }}
                ></div>
                <span>{method}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Winners Analysis */}
      <div className="mt-8 grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Best Performers */}
        <div className="bg-white p-6 rounded-xl shadow-lg border border-gray-200">
          <h4 className="text-xl font-semibold text-gray-800 mb-4 text-center">🏆 Best Performers</h4>
          <div className="space-y-4">
            <div className="border-l-4 border-yellow-500 pl-4 py-2">
              <h5 className="font-medium text-gray-900">Overall Champion</h5>
              <p className="text-sm text-gray-600">
                <span className="font-semibold">{winnersAnalysis.bestOverall?.method}</span> - {winnersAnalysis.bestOverall?.language}
                <br />Score: {winnersAnalysis.bestOverall?.maxScore?.toFixed(2)} 
                @ {winnersAnalysis.bestOverall?.optimalDocCount} docs
              </p>
            </div>
            
            <div className="border-l-4 border-green-500 pl-4 py-2">
              <h5 className="font-medium text-gray-900">Most Consistent</h5>
              <p className="text-sm text-gray-600">
                <span className="font-semibold">{winnersAnalysis.mostConsistent?.method}</span> - {winnersAnalysis.mostConsistent?.language}
                <br />Std Dev: {winnersAnalysis.mostConsistent?.consistency?.toFixed(2)}
              </p>
            </div>
            
            <div className="border-l-4 border-blue-500 pl-4 py-2">
              <h5 className="font-medium text-gray-900">Best Improvement</h5>
              <p className="text-sm text-gray-600">
                <span className="font-semibold">{winnersAnalysis.bestImprovement?.method}</span> - {winnersAnalysis.bestImprovement?.language}
                <br />Gain: +{winnersAnalysis.bestImprovement?.improvement?.toFixed(2)}
              </p>
            </div>
          </div>
        </div>

        {/* Language Winners */}
        <div className="bg-white p-6 rounded-xl shadow-lg border border-gray-200">
          <h4 className="text-xl font-semibold text-gray-800 mb-4 text-center">🌐 Best per Language</h4>
          <div className="space-y-3">
            {Object.entries(winnersAnalysis.bestPerLanguage || {}).map(([lang, winner]) => (
              <div key={lang} className="flex justify-between items-center p-3 bg-gray-50 rounded-lg">
                <div>
                  <span className="font-medium text-gray-900">{lang}</span>
                  <br />
                  <span className="text-sm text-gray-600">{winner.method}</span>
                </div>
                <div className="text-right">
                  <div className="font-bold text-lg" style={{ color: COLORS[lang] }}>
                    {winner.maxScore.toFixed(1)}
                  </div>
                  <div className="text-xs text-gray-500">{winner.optimalDocCount} docs</div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Comprehensive Comparison Table */}
      <div className="mt-8 bg-white p-6 rounded-xl shadow-lg border border-gray-200">
        <h4 className="text-xl font-semibold text-gray-800 mb-4 text-center">📊 Detailed Comparison Table</h4>
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Method</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Language</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Max Score</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Mean Score</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Min Score</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Optimal Docs</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Improvement</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Consistency</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {comparisonStats.map((stat, index) => (
                <tr key={index} className="hover:bg-gray-50">
                  <td className="px-4 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{stat.method}</td>
                  <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-900">
                    <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium" 
                          style={{ backgroundColor: COLORS[stat.language] + '20', color: COLORS[stat.language] }}>
                      {stat.language}
                    </span>
                  </td>
                  <td className="px-4 py-4 whitespace-nowrap text-sm font-bold text-gray-900">{stat.maxScore.toFixed(2)}</td>
                  <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-900">{stat.meanScore.toFixed(2)}</td>
                  <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-900">{stat.minScore.toFixed(2)}</td>
                  <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-900">{stat.optimalDocCount}</td>
                  <td className={`px-4 py-4 whitespace-nowrap text-sm font-medium ${stat.improvement >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                    {stat.improvement >= 0 ? '+' : ''}{stat.improvement.toFixed(2)}
                  </td>
                  <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-900">{stat.consistency.toFixed(2)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default MethodComparisonView;