import React from 'react';

const CustomLegend = ({ payload }) => {
  if (!payload || !payload.length) {
    return null;
  }

  return (
    <div 
      className="flex flex-wrap justify-center items-center p-3 rounded-xl border border-white/20 mx-auto max-w-fit"
      style={{
        background: 'rgba(255, 255, 255, 0.85)',
        backdropFilter: 'blur(10px)',
        WebkitBackdropFilter: 'blur(10px)',
        boxShadow: '0 8px 32px 0 rgba(31, 38, 135, 0.37)',
      }}
    >
      {payload.map((entry, index) => (
        <div 
          key={index} 
          className="flex items-center mx-2 my-1 text-sm font-medium text-gray-800"
        >
          <span 
            className="inline-block w-3 h-3 rounded-full mr-2 shadow-sm" 
            style={{ backgroundColor: entry.color }}
          ></span>
          <span>{entry.value}</span>
        </div>
      ))}
    </div>
  );
};

export default CustomLegend;