import React from 'react';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import { COLORS } from '../../constants';
import CustomTooltip from '../CustomTooltip';
import CustomLegend from '../CustomLegend';
import ExplanationCard from '../ExplanationCard';

const BarChartView = ({ selectedMethod, selectedModel, chartData, selectedLanguages }) => {
  // Convert chartData format to match original (documents -> docCount)
  const barData = chartData.map(item => ({
    docCount: item.documents,
    ...Object.fromEntries(
      selectedLanguages.map(lang => [lang, item[lang]])
    )
  }));

  return (
    <div className="mb-8">
      <ExplanationCard title="Bar Chart Analysis Explanation">
        <p><strong>Bar Chart:</strong> Compares performance scores across different document counts for each language.</p>
        <p><strong>Each Bar Group:</strong> Represents a specific document count (0, 1, 3, 5, 10, 20, 32).</p>
        <p><strong>Color Coding:</strong> Each language has a distinct color for easy comparison across document counts.</p>
        <p><strong>Interpretation:</strong> Taller bars indicate better performance. Compare bar heights within groups to see language differences at each document count.</p>
      </ExplanationCard>

      <h3 className="text-3xl font-bold text-gray-800 mb-3 text-center">
        Performance Bar Analysis
      </h3>
      <p className="text-lg text-gray-600 text-center mb-8">
        Compare performance across document counts for {selectedMethod} method - {selectedModel} model.
      </p>
      
      <div className="bg-gray-50 rounded-xl p-8 shadow-inner border border-gray-200">
        <ResponsiveContainer width="100%" height={500}>
          <BarChart data={barData} margin={{ top: 20, right: 40, left: 20, bottom: 60 }}>
            <CartesianGrid strokeDasharray="4 4" stroke="#e0e7ff" />
            <XAxis
              dataKey="docCount"
              label={{ value: 'Number of Documents (Doc Count)', position: 'bottom', offset: 25, fill: '#4a5568', fontSize: '15px', fontWeight: 'bold' }}
              tickLine={false}
              axisLine={{ stroke: '#cbd5e0' }}
              padding={{ left: 15, right: 15 }}
            />
            <YAxis
              label={{ value: 'Performance Score', angle: -90, position: 'left', offset: 10, fill: '#4a5568', fontSize: '15px', fontWeight: 'bold' }}
              tickLine={false}
              axisLine={{ stroke: '#cbd5e0' }}
              domain={['dataMin - 10', 'dataMax + 10']}
            />
            <Tooltip content={<CustomTooltip />} />
            <Legend content={<CustomLegend />} />
            {selectedLanguages.map(lang => (
              <Bar 
                key={lang} 
                dataKey={lang} 
                fill={COLORS[lang]} 
                name={lang} 
                barSize={30}
              />
            ))}
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default BarChartView;