import React from 'react';
import {
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import { COLORS } from '../../constants';
import CustomTooltip from '../CustomTooltip';
import CustomLegend from '../CustomLegend';
import ExplanationCard from '../ExplanationCard';

const AreaChartView = ({ selectedMethod, selectedModel, chartData, selectedLanguages }) => {
  // Convert chartData format to match original (documents -> docCount)
  const areaData = chartData.map(item => ({
    docCount: item.documents,
    ...Object.fromEntries(
      selectedLanguages.map(lang => [lang, item[lang]])
    )
  }));

  return (
    <div className="mb-8">
      <ExplanationCard title="Area Chart Analysis Explanation">
        <p><strong>Area Chart:</strong> Shows cumulative performance trends with filled areas under each line.</p>
        <p><strong>Filled Areas:</strong> Each language's performance is represented by a colored area, making it easy to see overall performance patterns.</p>
        <p><strong>Layered View:</strong> Areas are stacked to show both individual and cumulative performance across languages.</p>
        <p><strong>Interpretation:</strong> Larger filled areas indicate better sustained performance across document counts.</p>
      </ExplanationCard>

      <h3 className="text-3xl font-bold text-gray-800 mb-3 text-center">
        Performance Area Analysis
      </h3>
      <p className="text-lg text-gray-600 text-center mb-8">
        Area chart visualization for {selectedMethod} method - {selectedModel} model.
      </p>
      
      <div className="bg-gray-50 rounded-xl p-8 shadow-inner border border-gray-200">
        <ResponsiveContainer width="100%" height={500}>
          <AreaChart data={areaData} margin={{ top: 20, right: 40, left: 20, bottom: 60 }}>
            <CartesianGrid strokeDasharray="4 4" stroke="#e0e7ff" />
            <XAxis
              dataKey="docCount"
              label={{ value: 'Number of Documents (Doc Count)', position: 'bottom', offset: 25, fill: '#4a5568', fontSize: '15px', fontWeight: 'bold' }}
              tickLine={false}
              axisLine={{ stroke: '#cbd5e0' }}
              padding={{ left: 15, right: 15 }}
              interval="preserveStartEnd"
            />
            <YAxis
              label={{ value: 'Performance Score', angle: -90, position: 'left', offset: 10, fill: '#4a5568', fontSize: '15px', fontWeight: 'bold' }}
              tickLine={false}
              axisLine={{ stroke: '#cbd5e0' }}
              domain={['dataMin - 10', 'dataMax + 10']}
            />
            <Tooltip content={<CustomTooltip />} />
            <Legend content={<CustomLegend />} />
            {selectedLanguages.map(lang => (
              <Area
                key={lang}
                type="monotone"
                dataKey={lang}
                stroke={COLORS[lang]}
                fill={COLORS[lang]}
                fillOpacity={0.3}
                strokeWidth={2}
                name={lang}
              />
            ))}
          </AreaChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default AreaChartView;