import React from 'react';
import {
  ScatterChart, Scatter, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, Cell
} from 'recharts';
import { COLORS } from '../../constants';
import CustomLegend from '../CustomLegend';
import ExplanationCard from '../ExplanationCard';

const ScatterChartView = ({ selectedMethod, selectedModel, chartData, selectedLanguages }) => {
  // Convert data to scatter plot format with individual points for each language
  const scatterData = [];
  chartData.forEach((item) => {
    selectedLanguages.forEach(lang => {
      if (item[lang] !== null && item[lang] !== undefined) {
        scatterData.push({
          docCount: item.documents,
          performance: item[lang],
          language: lang,
          color: COLORS[lang]
        });
      }
    });
  });

  return (
    <div className="mb-8">
      <ExplanationCard title="Scatter Plot Analysis Explanation">
        <p><strong>Scatter Plot:</strong> Shows individual data points for each language and document count combination.</p>
        <p><strong>X-Axis:</strong> Number of documents (0-32).</p>
        <p><strong>Y-Axis:</strong> Performance score for that specific configuration.</p>
        <p><strong>Color Coding:</strong> Each language is represented by a different colored dot.</p>
        <p><strong>Interpretation:</strong> Look for clusters, outliers, and patterns. Higher points indicate better performance.</p>
      </ExplanationCard>

      <h3 className="text-3xl font-bold text-gray-800 mb-3 text-center">
        Performance Scatter Analysis
      </h3>
      <p className="text-lg text-gray-600 text-center mb-8">
        Individual data points for {selectedMethod} method - {selectedModel} model.
      </p>
      
      <div className="bg-gray-50 rounded-xl p-8 shadow-inner border border-gray-200">
        <ResponsiveContainer width="100%" height={500}>
          <ScatterChart data={scatterData} margin={{ top: 20, right: 40, left: 20, bottom: 60 }}>
            <CartesianGrid strokeDasharray="4 4" stroke="#e0e7ff" />
            <XAxis
              type="number"
              dataKey="docCount"
              name="Document Count"
              label={{ value: 'Number of Documents (Doc Count)', position: 'bottom', offset: 25, fill: '#4a5568', fontSize: '15px', fontWeight: 'bold' }}
              tickLine={false}
              axisLine={{ stroke: '#cbd5e0' }}
              domain={['dataMin - 1', 'dataMax + 1']}
            />
            <YAxis
              type="number"
              dataKey="performance"
              name="Performance"
              label={{ value: 'Performance Score', angle: -90, position: 'left', offset: 10, fill: '#4a5568', fontSize: '15px', fontWeight: 'bold' }}
              tickLine={false}
              axisLine={{ stroke: '#cbd5e0' }}
              domain={['dataMin - 10', 'dataMax + 10']}
            />
            <Tooltip 
              formatter={(value, name) => [value?.toFixed(2), name]}
              labelFormatter={(label, payload) => `Document Count: ${payload?.[0]?.payload?.docCount || label}`}
            />
            <Legend content={<CustomLegend />} />
            <Scatter name="Performance Data" dataKey="performance" fill="#8884d8">
              {scatterData.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={entry.color} />
              ))}
            </Scatter>
          </ScatterChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default ScatterChartView;