import React from 'react';
import { COLORS } from '../constants';

const ControlPanel = ({
  fileInfo,
  selectedMethod,
  setSelectedMethod,
  selectedModel,
  setSelectedModel,
  viewType,
  setViewType,
  selectedLanguages,
  setSelectedLanguages,
  selectedMethodsForComparison,
  setSelectedMethodsForComparison,
  comparisonModel,
  setComparisonModel,
  heatmapMetric,
  setHeatmapMetric,
  statisticalView,
  setStatisticalView,
  methodData
}) => {
  const methods = Object.keys(methodData);
  const models = selectedMethod ? Object.keys(methodData[selectedMethod] || {}) : [];

  return (
    <section className="mb-6">
      <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-200">
        <div className="flex items-center mb-6 justify-center">
          <h2 className="text-xl font-bold text-gray-800">Analysis Controls</h2>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {/* Method Selection */}
          <div className="space-y-3">
            <label htmlFor="method-select" className="block text-base font-semibold text-gray-700">Method</label>
            <select
              id="method-select"
              value={selectedMethod}
              onChange={(e) => setSelectedMethod(e.target.value)}
              className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-colors duration-200"
            >
              {methods.map(method => (
                <option key={method} value={method}>{method}</option>
              ))}
            </select>
          </div>

          {/* Model Selection */}
          <div className="space-y-3">
            <label htmlFor="model-select" className="block text-base font-semibold text-gray-700">Model</label>
            <select
              id="model-select"
              value={selectedModel}
              onChange={(e) => setSelectedModel(e.target.value)}
              className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-colors duration-200"
            >
              {models.map(model => (
                <option key={model} value={model}>{model}</option>
              ))}
            </select>
          </div>

          {/* View Type Selection */}
          <div className="space-y-3">
            <label htmlFor="view-select" className="block text-base font-semibold text-gray-700">View Type</label>
            <select
              id="view-select"
              value={viewType}
              onChange={(e) => setViewType(e.target.value)}
              className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-colors duration-200"
            >
              <option value="lines">Line Chart</option>
              <option value="bars">Bar Chart</option>
              <option value="scatter">Scatter Plot</option>
              <option value="area">Area Chart</option>
              <option value="heatmap">Heatmap</option>
              <option value="methodComparison">Method Comparison</option>
              <option value="statistical">Statistical Analysis</option>
              <option value="comprehensive">Comprehensive Overview</option>
            </select>
          </div>

          {/* Statistical View Selection (for statistical view type) */}
          {viewType === 'statistical' && (
            <div className="space-y-3">
              <label className="block text-base font-semibold text-gray-700">Statistical View</label>
              <div className="flex flex-wrap gap-2">
                {['mean', 'std', 'max', 'min', 'trend'].map(stat => (
                  <button
                    key={stat}
                    onClick={() => setStatisticalView(stat)}
                    className={`px-3 py-2 text-sm font-medium rounded-lg border transition-colors duration-200 ${
                      statisticalView === stat 
                        ? 'bg-indigo-500 text-white border-indigo-500' 
                        : 'text-gray-700 border-gray-300 bg-white hover:bg-gray-50'
                    }`}
                  >
                    {stat.charAt(0).toUpperCase() + stat.slice(1)}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Language Selection */}
        <div className="mt-8 pt-6 border-t border-gray-200">
          <h3 className="text-lg font-semibold text-gray-700 mb-4 text-center">Language Selection</h3>
          <div className="flex flex-wrap gap-3 justify-center">
            {Object.keys(COLORS).map(lang => (
              <button
                key={lang}
                onClick={() => {
                  setSelectedLanguages(prev =>
                    prev.includes(lang)
                      ? prev.filter(l => l !== lang)
                      : [...prev, lang].sort()
                  );
                }}
                className={`px-3 py-2 rounded-lg border-2 font-semibold text-sm transition-all duration-200 ${
                  selectedLanguages.includes(lang)
                    ? 'transform scale-105 shadow-md'
                    : 'hover:scale-102'
                }`}
                style={{
                  backgroundColor: selectedLanguages.includes(lang) ? COLORS[lang] : 'transparent',
                  color: selectedLanguages.includes(lang) ? 'white' : COLORS[lang],
                  borderColor: COLORS[lang]
                }}
              >
                {lang}
              </button>
            ))}
          </div>
        </div>

        {/* Method Comparison Controls */}
        {viewType === 'methodComparison' && (
          <div className="mt-8 pt-8 border-t border-gray-200">
            <h3 className="text-xl font-semibold text-gray-700 mb-6 text-center">Method Comparison Settings</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-3">
                <label className="block text-base font-semibold text-gray-700">Select Methods to Compare</label>
                <div className="space-y-2">
                  {methods.map(method => (
                    <label key={method} className="flex items-center">
                      <input
                        type="checkbox"
                        checked={selectedMethodsForComparison.includes(method)}
                        onChange={(e) => {
                          if (e.target.checked) {
                            setSelectedMethodsForComparison(prev => [...prev, method]);
                          } else {
                            setSelectedMethodsForComparison(prev => prev.filter(m => m !== method));
                          }
                        }}
                        className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded"
                      />
                      <span className="ml-2 text-sm text-gray-700">{method}</span>
                    </label>
                  ))}
                </div>
              </div>
              
              <div className="space-y-3">
                <label htmlFor="comparison-model-select" className="block text-base font-semibold text-gray-700">Model for Comparison</label>
                <select
                  id="comparison-model-select"
                  value={comparisonModel}
                  onChange={(e) => setComparisonModel(e.target.value)}
                  className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-colors duration-200"
                >
                  {fileInfo?.models.map(model => (
                    <option key={model} value={model}>{model}</option>
                  ))}
                </select>
              </div>
            </div>
          </div>
        )}

        {/* Heatmap Controls */}
        {viewType === 'heatmap' && (
          <div className="mt-8 pt-8 border-t border-gray-200 text-center">
            <label className="block text-base font-semibold text-gray-700 mb-4">Heatmap Display Metric</label>
            <div className="flex flex-wrap gap-4 justify-center">
              {['absolute', 'improvement', 'relative'].map(metric => (
                <button
                  key={metric}
                  onClick={() => setHeatmapMetric(metric)}
                  className={`px-6 py-3 text-sm font-medium rounded-lg border-2 transition-colors duration-200 ${
                    heatmapMetric === metric 
                      ? 'bg-violet-500 text-white border-violet-500' 
                      : 'text-gray-700 border-gray-300 bg-white hover:bg-gray-50'
                  }`}
                >
                  {metric.charAt(0).toUpperCase() + metric.slice(1)}
                </button>
              ))}
            </div>
          </div>
        )}
      </div>
    </section>
  );
};

export default ControlPanel;