import React from 'react';
import Header from './components/Header';
import DataLoaderSection from './components/DataLoaderSection';
import ControlPanel from './components/ControlPanel';
import VisualizationContainer from './components/VisualizationContainer';
import EmptyState from './components/EmptyState';
import { useDataState } from './hooks/useDataState';
import { useVisualizationState } from './hooks/useVisualizationState';
import { useComparisonState } from './hooks/useComparisonState';

const MedExpQAAnalysis = () => {
  const dataState = useDataState();
  const visualizationState = useVisualizationState();
  const comparisonState = useComparisonState();

  const {
    methodData,
    fileInfo,
    isLoading,
    error,
    googleSheetsUrl,
    setGoogleSheetsUrl
  } = dataState;

  const {
    selectedModel,
    setSelectedModel,
    viewType,
    setViewType,
    selectedMethod,
    setSelectedMethod,
    selectedLanguages,
    setSelectedLanguages,
    heatmapMetric,
    setHeatmapMetric,
    statisticalView,
    setStatisticalView
  } = visualizationState;

  const {
    selectedMethodsForComparison,
    setSelectedMethodsForComparison,
    comparisonModel,
    setComparisonModel
  } = comparisonState;

  const hasData = Object.keys(methodData).length > 0;

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50 font-sans text-gray-900">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        
        <Header />

        <DataLoaderSection
          googleSheetsUrl={googleSheetsUrl}
          setGoogleSheetsUrl={setGoogleSheetsUrl}
          isLoading={isLoading}
          error={error}
          setIsLoading={dataState.setIsLoading}
          setError={dataState.setError}
          setMethodData={dataState.setMethodData}
          setFileInfo={dataState.setFileInfo}
          setSelectedMethod={visualizationState.setSelectedMethod}
          setSelectedModel={visualizationState.setSelectedModel}
          setComparisonModel={comparisonState.setComparisonModel}
          setSelectedMethodsForComparison={comparisonState.setSelectedMethodsForComparison}
        />

        {hasData ? (
          <>
            <ControlPanel
              fileInfo={fileInfo}
              selectedMethod={selectedMethod}
              setSelectedMethod={setSelectedMethod}
              selectedModel={selectedModel}
              setSelectedModel={setSelectedModel}
              viewType={viewType}
              setViewType={setViewType}
              selectedLanguages={selectedLanguages}
              setSelectedLanguages={setSelectedLanguages}
              selectedMethodsForComparison={selectedMethodsForComparison}
              setSelectedMethodsForComparison={setSelectedMethodsForComparison}
              comparisonModel={comparisonModel}
              setComparisonModel={setComparisonModel}
              heatmapMetric={heatmapMetric}
              setHeatmapMetric={setHeatmapMetric}
              statisticalView={statisticalView}
              setStatisticalView={setStatisticalView}
              methodData={methodData}
            />

            <VisualizationContainer
              viewType={viewType}
              selectedMethod={selectedMethod}
              selectedModel={selectedModel}
              methodData={methodData}
              selectedLanguages={selectedLanguages}
              heatmapMetric={heatmapMetric}
              statisticalView={statisticalView}
              selectedMethodsForComparison={selectedMethodsForComparison}
              comparisonModel={comparisonModel}
            />
          </>
        ) : (
          <EmptyState />
        )}
      </div>
    </div>
  );
};

export default MedExpQAAnalysis;
