import React, { useCallback } from 'react';
import { handleExcelFileUpload, handleLoadFromGoogleSheets } from '../utils/dataLoading';

const DataLoaderSection = ({
  googleSheetsUrl,
  setGoogleSheetsUrl,
  isLoading,
  error,
  setIsLoading,
  setError,
  setMethodData,
  setFileInfo,
  setSelectedMethod,
  setSelectedModel,
  setComparisonModel,
  setSelectedMethodsForComparison
}) => {
  const handleFileUpload = useCallback((file) => {
    handleExcelFileUpload(file, { 
      setIsLoading, 
      setError, 
      setMethodData, 
      setFileInfo, 
      setSelectedMethod, 
      setSelectedModel, 
      setComparisonModel, 
      setSelectedMethodsForComparison 
    });
  }, [setIsLoading, setError, setMethodData, setFileInfo, setSelectedMethod, setSelectedModel, setComparisonModel, setSelectedMethodsForComparison]);

  const handleGoogleSheetsLoad = useCallback(() => {
    handleLoadFromGoogleSheets(googleSheetsUrl, { 
      setIsLoading, 
      setError, 
      setMethodData, 
      setFileInfo, 
      setSelectedMethod, 
      setSelectedModel, 
      setComparisonModel, 
      setSelectedMethodsForComparison 
    });
  }, [googleSheetsUrl, setIsLoading, setError, setMethodData, setFileInfo, setSelectedMethod, setSelectedModel, setComparisonModel, setSelectedMethodsForComparison]);

  return (
    <section className="mb-6">
      <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-200 transform transition-transform duration-300 ease-in-out hover:scale-[1.01]">
        <div className="flex items-center mb-4 justify-center">
          <h2 className="text-xl font-bold text-gray-800">Load Your Data</h2>
        </div>

        {/* Google Sheets Section */}
        <div className="mb-4 p-3 bg-blue-50 rounded-lg border border-blue-200">
          <h3 className="text-lg font-semibold text-gray-700 mb-2 flex items-center justify-center">
            <span className="w-6 h-6 bg-green-200 rounded-full flex items-center justify-center mr-2 text-sm">📄</span>
            Load from Google Sheets URL
          </h3>
          <div className="flex flex-col sm:flex-row gap-2 justify-center">
            <input
              type="url"
              value={googleSheetsUrl}
              onChange={(e) => setGoogleSheetsUrl(e.target.value)}
              className="flex-1 px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-colors duration-200"
            />
            <button
              onClick={handleGoogleSheetsLoad}
              disabled={isLoading || !googleSheetsUrl.trim()}
              className="px-4 py-2 bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-700 focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed transition-colors duration-200"
            >
              {isLoading ? (
                <span className="flex items-center">
                  <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" fill="none" viewBox="0 0 24 24">
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  Loading...
                </span>
              ) : 'Load Data'}
            </button>
          </div>
          <p className="text-xs text-gray-600 mt-2 text-center">
            <span className="font-semibold">Important:</span> Ensure your Google Sheet's sharing settings are set to "Anyone with the link" and "Viewer".
          </p>
        </div>

        {/* File Upload Section */}
        <div className="mb-4 p-3 bg-purple-50 rounded-lg border border-purple-200">
          <h3 className="text-lg font-semibold text-gray-700 mb-2 flex items-center justify-center">
            <span className="w-6 h-6 bg-purple-200 rounded-full flex items-center justify-center mr-2 text-sm">📁</span>
            Upload Excel File (.xlsx)
          </h3>
          <div className="flex justify-center">
            <input
              type="file"
              accept=".xlsx,.xls"
              onChange={(e) => e.target.files?.[0] && handleFileUpload(e.target.files[0])}
              disabled={isLoading}
              className="file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0 file:text-sm file:font-semibold file:bg-purple-600 file:text-white hover:file:bg-purple-700 file:cursor-pointer disabled:opacity-50"
            />
          </div>
        </div>

        {/* Error Display */}
        {error && (
          <div className="mt-4 p-3 bg-red-50 border border-red-200 rounded-lg">
            <p className="text-red-700 text-sm font-medium">{error}</p>
          </div>
        )}
      </div>
    </section>
  );
};

export default DataLoaderSection;