import React, { useMemo } from 'react';
import _ from 'lodash';
import { DOC_COUNTS, LANGUAGES } from '../../constants';
import ExplanationCard from '../ExplanationCard';

const HeatmapView = ({ selectedMethod, selectedModel, methodData, heatmapMetric }) => {
  // Helper function to calculate cell background color for heatmap
  const getHeatmapCellColor = (value, minVal, maxVal, type) => {
    if (isNaN(value) || value === null || value === 'N/A') return '#f3f4f6'; // gray-100
    if (type === 'absolute') {
      const normalizedValue = maxVal === minVal ? 0.5 : (value - minVal) / (maxVal - minVal);
      const greenIntensity = Math.floor(normalizedValue * 180) + 70;
      return `rgb(70, ${greenIntensity}, 70)`;
    } else {
      const effectiveMaxAbs = Math.max(Math.abs(minVal), Math.abs(maxVal), 0.001);
      const normalizedValue = value / effectiveMaxAbs;
      if (value > 0) {
        return `rgba(60, 179, 113, ${0.3 + normalizedValue * 0.7})`;
      } else if (value < 0) {
        return `rgba(220, 20, 60, ${0.3 + Math.abs(normalizedValue) * 0.7})`;
      } else {
        return '#f5f5f5'; // Light grey for zero/no change
      }
    }
  };

  const heatmapDisplayValues = useMemo(() => {
    if (!selectedMethod || !methodData[selectedMethod] || !selectedModel) {
      return { data: [], minGlobal: 0, maxGlobal: 0 };
    }
    
    const allDisplayValues = [];
    const dataForTable = [];
    
    if (methodData[selectedMethod][selectedModel]) {
      LANGUAGES.forEach(lang => {
        const values = methodData[selectedMethod][selectedModel][lang] || [];
        values.forEach((value, docIndex) => {
          let displayValue = value;
          if (heatmapMetric === 'improvement' && docIndex > 0) {
            displayValue = value - (values[0] || 0);
          } else if (heatmapMetric === 'relative' && values[0] !== 0) {
            displayValue = ((value - values[0]) / values[0]) * 100;
          }
          
          if (displayValue !== null && displayValue !== undefined && !isNaN(displayValue)) {
            allDisplayValues.push(displayValue);
          }
          
          dataForTable.push({
            language: lang,
            docCount: DOC_COUNTS[docIndex],
            displayValue: (displayValue === null || displayValue === undefined || isNaN(displayValue)) ? 'N/A' : displayValue.toFixed(2),
            rawValue: value
          });
        });
      });
    }
    
    const minGlobal = allDisplayValues.length > 0 ? Math.min(...allDisplayValues) : 0;
    const maxGlobal = allDisplayValues.length > 0 ? Math.max(...allDisplayValues) : 0;
    
    return { data: dataForTable, minGlobal, maxGlobal };
  }, [selectedMethod, selectedModel, methodData, heatmapMetric]);

  const { data, minGlobal, maxGlobal } = heatmapDisplayValues;

  return (
    <div className="mb-8">
      <ExplanationCard title="Heatmap Analysis Explanation">
        <div className="space-y-2">
          {heatmapMetric === 'absolute' && (
            <div>
              <p><strong>Absolute Values:</strong> Shows the raw performance scores as they are.</p>
              <p>Higher values (darker green) indicate better performance. This view is best for seeing overall magnitude differences between conditions.</p>
            </div>
          )}
          {heatmapMetric === 'improvement' && (
            <div>
              <p><strong>Improvement Values:</strong> Shows the difference from the baseline (0 documents).</p>
              <p>Calculated as: Current Score - Baseline Score. Positive values (green) show improvement, negative values (red) show decline from baseline.</p>
            </div>
          )}
          {heatmapMetric === 'relative' && (
            <div>
              <p><strong>Relative Values:</strong> Shows percentage change from the baseline (0 documents).</p>
              <p>Calculated as: ((Current Score - Baseline Score) / Baseline Score) × 100. Useful for comparing proportional improvements across different scales.</p>
            </div>
          )}
        </div>
      </ExplanationCard>

      <h3 className="text-3xl font-bold text-gray-800 mb-3 text-center">
        Performance Heatmap Overview
      </h3>
      <p className="text-lg text-gray-600 text-center mb-8">
        Showing <span className="text-purple-700 font-semibold">{heatmapMetric.charAt(0).toUpperCase() + heatmapMetric.slice(1)}</span> values for {selectedMethod} method - {selectedModel} model.
      </p>
      
      <div className="bg-gray-50 p-6 rounded-xl shadow-inner border border-gray-200 overflow-x-auto">
        <table className="min-w-full divide-y divide-gray-200 border border-gray-300">
          <thead>
            <tr className="bg-gray-100">
              <th className="px-5 py-4 border-r border-b border-gray-300 text-left text-sm font-semibold text-gray-700 uppercase tracking-wider min-w-[180px]">
                Language
              </th>
              {DOC_COUNTS.map(count => (
                <th key={count} className="px-5 py-4 border-r border-b border-gray-300 text-center text-sm font-semibold text-gray-700 uppercase tracking-wider">
                  {count} docs
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {LANGUAGES.map((lang, langIdx) => {
              const rowData = data.filter(d => d.language === lang);
              return (
                <tr
                  key={lang}
                  className={`${langIdx % 2 === 0 ? 'bg-white' : 'bg-gray-50'} hover:bg-gray-100 transition-colors duration-150`}
                >
                  <td className="px-5 py-3 border-r border-gray-300 font-medium text-sm text-gray-900 sticky left-0 bg-inherit z-10">
                    {lang}
                  </td>
                  {rowData.map((cell, idx) => {
                    const isOptimalHighlight = heatmapMetric === 'absolute' &&
                      cell.rawValue === _.max(methodData[selectedMethod]?.[selectedModel]?.[lang] || []) &&
                      cell.rawValue !== undefined && cell.rawValue !== null;
                    return (
                      <td
                        key={idx}
                        className={`px-5 py-3 text-center text-sm border-r border-gray-300 transition-colors duration-200
                                    ${isOptimalHighlight ? 'font-bold ring-2 ring-blue-500 rounded-md scale-105 transform' : ''}`}
                        style={{ backgroundColor: getHeatmapCellColor(parseFloat(cell.displayValue), minGlobal, maxGlobal, heatmapMetric) }}
                        title={`Doc Count: ${cell.docCount}\nDisplay Value: ${cell.displayValue}\nRaw Value: ${cell.rawValue?.toFixed(2) || 'N/A'}`}
                      >
                        {cell.displayValue}
                      </td>
                    );
                  })}
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default HeatmapView;